backup.running:
firewall {
    all-ping enable
    name WAN_IN {
        default-action drop
    }
}
interfaces {
    ethernet eth0 {
        address dhcp
        description WAN
    }
    ethernet eth1 {
        address 192.168.1.1/24
    }
}
service {
    ssh {
        port 22
        protocol-version v2
    }
}
system {
    host-name EdgeRouter
    login {
        user ubnt {
            level admin
        }
    }
}
